UPDATE public.vault_articles SET title = $v$Mind: Three Time-Scales, Three Tools$v$, subtitle = $v$Emotion is a skill, and each tool fits one moment$v$, summary = $v$Emotional regulation is a trained skill, not a fixed trait. This shelf gives you a tool for three different moments: the spike that lasts seconds, the daily baseline, and the patterns that run for years.$v$, evidence_tier = $v$strong$v$, protocol = $v${}$v$::jsonb, benefits = ARRAY[$v$Emotion reframed as trainable, not fixed$v$, $v$Each tool mapped to the moment it fits$v$, $v$Removes the trap of treating a mood as a personality$v$], risks = ARRAY[$v$Not a substitute for therapy in depression, trauma or an anxiety disorder$v$, $v$Skills are installed in calm moments; a first attempt mid-crisis will disappoint$v$], body_md = $v$**Three time-scales**
An emotion runs on three clocks at once, and each clock needs its own tool. The spike: adrenaline in the first sixty seconds of a hard conversation or a missed lift, where only the body is fast enough. That is the breath, lessons 2 and 3. The baseline: the mood you wake into and carry through a normal Tuesday, which ten minutes of attention training a day moves over eight weeks. That is lesson 4. The pattern: the interpretation you reach for every time, the one that turns a late reply into rejection. That is lesson 5, cognitive reframing, and it works in weeks, not seconds. Then two practices for the mind at work: deep attention, and a five-minute journal.

**Why all three**
Only the acute tools and you are forever putting out fires. Only the daily practice and the baseline is calmer while the spikes still take you. Only the reframing and the thinking is more accurate while the body still races. The tools do different jobs; the common mistake is meditating through a panic spike, or breathing through a pattern that has run for ten years.

**What this shelf skips**
Therapy modalities with a name, which belong with a therapist. Long retreats, which are useful and not foundational. Psychedelics, where the trials are early and the setting is everything. And the habit mechanics that used to sit here as a cut-down of James Clear; the Wisdom shelf has the whole lesson.

**The usual mistake**
Waiting until you feel bad to try any of this. These are skills. They are installed in easy moments so that they are there in hard ones. Practise the breath when nothing is wrong, and it will answer when something is.

**How to read this shelf**
Seven lessons, read in order. Every one closes with something to do today, and the doing is what counts.$v$, why_it_matters = $v$Most people grab the wrong tool for the moment. Matching the tool to the clock is the whole trick, and once you can name the clock, every technique on this shelf works better.$v$, try_today = ARRAY[$v$Pick one recurring moment this week where emotion takes the wheel: a meeting, a commute, a conversation.$v$, $v$Name its clock: a spike, the baseline, or a pattern.$v$, $v$Write it down. You will come back to it at lesson 5.$v$], key_takeaways = ARRAY[$v$Emotion is trainable; treat it like strength: progressive, repeatable, measurable.$v$, $v$One clock, one tool: spike, breath; baseline, attention; pattern, reframing.$v$, $v$Train in calm moments so the skill is there in hard ones.$v$], quiz = $v$[{"q": "Which tool fits a spike that lasts under a minute?", "choices": ["The breath", "Mindfulness", "Cognitive reframing"], "correct": 0, "explain": "Adrenaline is faster than reasoning; only the body can answer inside a minute. Reframing and attention training need a calmer baseline and more time."}, {"q": "Why three tools?", "choices": ["You do not need three", "Spikes, the baseline and patterns run on different clocks", "Only the breath works"], "correct": 1, "explain": "Acute tools handle spikes, daily practice raises the baseline, reframing changes the pattern. They do different jobs."}]$v$::jsonb, references_json = $v$[{"author": "Hofmann, S. G., Asnaani, A., Vonk, I. J. J., Sawyer, A. T. & Fang, A.", "title": "The efficacy of cognitive behavioral therapy: a review of meta-analyses (Cogn. Ther. Res.)", "year": 2012}, {"author": "Goyal, M. et al.", "title": "Meditation programs for psychological stress and well-being: a systematic review and meta-analysis (JAMA Intern. Med.)", "year": 2014}, {"author": "Balban, M. Y. et al.", "title": "Brief structured respiration practices enhance mood and reduce physiological arousal (Cell Rep. Med.)", "year": 2023}]$v$::jsonb, reflect_prompt = $v$Which clock does your hardest moment run on, and which tool have you been reaching for?$v$, integrate_prompt = $v$A week of naming the clock. Did the tool you reached for change?$v$, practice_minutes = 5, lesson_number = 1, display_order = 1, course_role = $v$foundations$v$, read_time_min = 2, updated_at = now() WHERE slug = 'foundations-mind-and-emotion';

UPDATE public.vault_articles SET title = $v$Box Breathing$v$, subtitle = $v$Four counts in, four held, four out, four held$v$, summary = $v$Four counts in, four held, four out, four held, for two to five minutes. A slow, even rhythm that settles the body before a hard moment; the physiological sigh is faster, this one is steadier.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "2 to 5 min", "frequency": "Before a high-pressure moment; as a wind-down", "intensity": "4-4-4-4 through the nose; 3-3-3-3 if rushed", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$Lower heart rate and blood pressure during the practice$v$, $v$Less felt tension within minutes$v$, $v$A clearer head before the hard thing$v$, $v$Free, silent, usable anywhere$v$], risks = ARRAY[$v$Pregnancy or a lung condition: shorten or skip the holds$v$, $v$Not while driving; the relaxation is real$v$, $v$Light-headedness in the first sessions means slow down, not push$v$], body_md = $v$**The pattern**
Inhale through the nose for four counts. Hold for four. Exhale through the nose for four. Hold for four. That is one box, and a five-minute session is about eighteen of them. Sit upright, eyes soft, and start with a full exhale so the first inhale has room. If four feels rushed, use three; if it feels easy after a week, five or six.

**Why it works**
Slow breathing at around six breaths a minute shifts the autonomic balance toward the parasympathetic branch, lowers heart rate and blood pressure during the practice, and calms the sense of effort; Russo et al. (2017) reviewed the physiology. The box is one way to get there: at four counts of about a second each it lands near six breaths a minute, and the holds keep the rhythm even. Popular accounts add a story about carbon dioxide tolerance and the holds recalibrating anxiety; that part is not established, and the practice does not need it.

**What the trial found**
In the Stanford breathing trial (Balban et al. 2023), box breathing was one of four arms practised five minutes a day for a month. It improved mood and lowered anxiety, as every arm did; cyclic sighing did slightly better on positive mood and breathing rate. So the box is a sound choice and not a uniquely powerful one, which is why the chip says promising rather than strong.

**Where to use it**
Five minutes before a presentation, a hard conversation or a call you have been avoiding. One or two minutes in traffic or after an argument. Between sets when the heart is racing and the next set needs a clear head. As a wind-down in bed, with the exhale lengthened to six.

**Where it came from**
The name comes from Mark Divine, a former Navy SEAL who taught it to trainees for the water. The physiology is older than the brand.$v$, why_it_matters = $v$You cannot think your way out of an adrenaline spike; the reasoning arrives after the body has decided. A slow, even rhythm is the fastest lever you carry everywhere, and it works whether or not you believe in it.$v$, try_today = ARRAY[$v$Choose one high-pressure moment today.$v$, $v$Sixty seconds before it, run four boxes: four in, four hold, four out, four hold, through the nose.$v$, $v$Rate your tension from one to ten before and after.$v$], key_takeaways = ARRAY[$v$Four, four, four, four, through the nose; two to five minutes.$v$, $v$Slow, even breathing settles the body; the holds are for rhythm, not for a special effect.$v$, $v$Steadier than the sigh and slower than the sigh; use it before something hard.$v$], quiz = $v$[{"q": "What is the box pattern?", "choices": ["Eight in, no hold, eight out", "Six in, two out, six in, two out", "Four in, four held, four out, four held"], "correct": 2, "explain": "Equal counts, through the nose. The rhythm lands near six breaths a minute, which is where slow breathing does its work."}, {"q": "In the Stanford trial, box breathing…", "choices": ["Improved mood and anxiety like every arm, slightly behind cyclic sighing", "Beat every other method", "Did nothing"], "correct": 0, "explain": "Balban 2023: all four practices helped; cyclic sighing was best on positive mood and breathing rate."}, {"q": "When is box breathing most useful?", "choices": ["Long meditation", "Before a high-pressure moment", "Instead of sleep"], "correct": 1, "explain": "It buys a settled body and a clear head for the next ten minutes. For the spike itself, the sigh is faster."}]$v$::jsonb, references_json = $v$[{"author": "Russo, M. A., Santarelli, D. M. & O'Rourke, D.", "title": "The physiological effects of slow breathing in the healthy human (Breathe)", "year": 2017}, {"author": "Balban, M. Y. et al.", "title": "Brief structured respiration practices enhance mood and reduce physiological arousal (Cell Rep. Med.)", "year": 2023}, {"author": "Divine, M.", "title": "The Way of the SEAL", "year": 2013}]$v$::jsonb, reflect_prompt = $v$What does the minute before a hard moment usually look like for you?$v$, integrate_prompt = $v$After a week of boxes before hard moments, what changed about the first sentence you said?$v$, practice_minutes = 5, lesson_number = 2, display_order = 2, course_role = $v$protocol$v$, read_time_min = 2, updated_at = now() WHERE slug = 'box-breathing';

UPDATE public.vault_articles SET title = $v$The Physiological Sigh$v$, subtitle = $v$Two inhales through the nose, one long exhale through the mouth$v$, summary = $v$Two short inhales through the nose, then a long exhale through the mouth, one to three times. It is the fastest breath pattern there is for an acute spike, and five minutes a day of it did the most for mood in the Stanford trial.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "1 to 3 breaths for a spike; 5 min as a daily practice", "frequency": "On demand; daily if you want the baseline effect", "intensity": "Double nasal inhale, exhale through the mouth about twice as long", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$Slows the heart within a breath or two$v$, $v$Best positive-mood result of four practices in the Stanford trial$v$, $v$Works in under a minute, anywhere, silently$v$], risks = ARRAY[$v$Light-headed lying down: sit up and slow the exhale$v$, $v$It does not treat an anxiety disorder; it buys a minute$v$], body_md = $v$**How to do it**
Inhale through the nose until the lungs feel about two-thirds full. Take a second, shorter sip on top, through the nose. Then exhale slowly through the mouth until you are empty, aiming for an exhale roughly twice as long as the two inhales together. One to three of these is the acute dose. Five minutes is the daily practice.

**Why two inhales**
The body does this by itself every few minutes. The second inhale re-opens the small air sacs that collapse over a run of shallow breaths, and the long exhale then offloads carbon dioxide efficiently; Vlemincx et al. (2010) describe the spontaneous sigh as a reset of the breathing pattern. Done on purpose, the same reset slows the heart within a breath or two, because a long exhale is the strongest voluntary signal the vagus nerve receives.

**The Stanford trial**
Balban et al. (2023) randomised 114 adults to five minutes a day for a month of one of four practices: cyclic sighing, box breathing, cyclic hyperventilation with retention, or mindfulness meditation. All four groups improved in mood and anxiety. Cyclic sighing improved positive mood the most and lowered the resting breathing rate the most, and the effect grew with the number of days practised. It is one trial with a well-designed comparison, and that is what earns the chip.

**When to use it**
The spike: one to three sighs, sixty seconds, done. Between meetings, instead of the phone. Before a hard conversation, so the first sentence comes out at the right speed. In bed, two or three minutes, when the mind is running. The Inner Work shelf's lesson on state uses it as the down-shift and points here; this lesson owns the dose.

**What it is not**
A cure for an anxiety disorder, or a reason to skip the slower work of lessons 4 and 5. It buys a minute of clear head. What you do with the minute is the skill.$v$, why_it_matters = $v$In a head-to-head trial the sigh did the most for mood, and it is the one tool here that works inside a minute. Learn it once and you carry it into every room.$v$, try_today = ARRAY[$v$Now: two inhales through the nose, one long exhale through the mouth. Three times.$v$, $v$Notice the shoulders and the jaw after the third.$v$, $v$Use it once today at the moment a spike starts, before you reply to anything.$v$], key_takeaways = ARRAY[$v$Two nasal inhales, one long mouth exhale; the exhale is the active ingredient.$v$, $v$One to three for a spike, five minutes a day for the baseline.$v$, $v$Best positive-mood result of the four arms in the Stanford trial.$v$], quiz = $v$[{"q": "How is the sigh performed?", "choices": ["Inhale through the mouth, exhale through the nose", "One slow inhale, then hold", "Two inhales through the nose, one long exhale through the mouth"], "correct": 2, "explain": "The second inhale re-opens the small air sacs; the long exhale offloads carbon dioxide and slows the heart."}, {"q": "What did the Stanford trial show?", "choices": ["All four practices helped; cyclic sighing improved positive mood most", "Meditation beat everything", "Only the sigh worked"], "correct": 0, "explain": "Balban 2023, 114 adults, five minutes a day for a month. The sigh led on positive mood and breathing rate."}]$v$::jsonb, references_json = $v$[{"author": "Balban, M. Y. et al.", "title": "Brief structured respiration practices enhance mood and reduce physiological arousal (Cell Rep. Med.)", "year": 2023}, {"author": "Vlemincx, E., Van Diest, I. & Van den Bergh, O.", "title": "Sighs as resetters of physiological state (Biol. Psychol.)", "year": 2010}]$v$::jsonb, reflect_prompt = $v$Where in your day does the spike usually come, and what do you do in the first minute?$v$, integrate_prompt = $v$A week of sighs at the spike. What did the first sentence after it sound like?$v$, practice_minutes = 5, lesson_number = 3, display_order = 3, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'physiological-sigh';

UPDATE public.vault_articles SET title = $v$Mindfulness: Ten Minutes a Day$v$, subtitle = $v$Attention training, eight weeks, and what the trials actually found$v$, summary = $v$Mindfulness is attention training with three decades of trials behind it. Ten minutes a day for eight weeks moves anxiety and attention by a small to moderate amount, and the full clinical course matched a first-line antidepressant in one trial.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "10 min a day", "frequency": "Daily for eight weeks, then keep it", "intensity": "Breath as the anchor; return without a verdict when the mind wanders", "prerequisites": "None; trauma history goes with a trauma-informed teacher"}$v$::jsonb, benefits = ARRAY[$v$Small to moderate reductions in anxiety and depression, replicated$v$, $v$Better attention control and working memory$v$, $v$Lower stress reactivity over weeks$v$, $v$Compounds with every week kept$v$], risks = ARRAY[$v$Trauma history: a trauma-informed teacher, not a recording$v$, $v$Weeks one and two are boring and restless; that is the work, not a sign$v$, $v$A recording is a start; the clinical results came from the full course with a teacher$v$], body_md = $v$**The evidence, honestly**
Goyal et al. (2014) pooled 47 trials for JAMA Internal Medicine and found moderate evidence that eight-week mindfulness programmes improve anxiety, depression and pain by small to moderate amounts, comparable to what active controls like exercise achieve, and no evidence that they beat them. Hoge et al. (2023) then ran a direct comparison: 276 adults with anxiety disorders, eight weeks of the full MBSR course against escitalopram, and the two were equivalent at the end. That is the full dose, with weekly classes and 45 minutes of daily practice. Ten minutes a day is a smaller dose with its own evidence: Basso et al. (2019) found that thirteen minutes a day for eight weeks improved mood, attention and working memory in people who had never meditated, while four weeks did not. Eight weeks is the number that keeps coming back.

**The practice**
Sit upright, eyes closed or lowered. Put attention on the breath, at the nostrils or the belly. Notice each breath without changing it. When attention wanders, and it will, dozens of times, notice that it has, and bring it back. That return is the repetition. The practice is not staying focused; it is noticing you have left and coming back, again, without a verdict.

**What it does over time**
Attention control improves and mind-wandering falls (Mrazek et al. 2013). The amygdala's response to negative images drops after training (Goldin and Gross 2010). Cortisol responses to stress fall in a pooled analysis (Pascoe et al. 2017). The famous brain-structure study (Hölzel et al. 2011) found more grey matter in the hippocampus after eight weeks in sixteen people; it is real and it is small, and it gets quoted as if it were large.

**How to keep it for eight weeks**
Same chair, same time, attached to the coffee or the pillow. Never miss two days in a row. Do not grade sessions; the ones that felt like a mess were the ones with the most returns. A guided recording helps in the first weeks if a teacher is not available, and which one does not matter.

**Who should do it with a teacher**
Anyone with a trauma history, for whom sitting with the body can flood rather than settle. A trauma-informed course changes the instructions, and that is the safer route.$v$, why_it_matters = $v$Mindfulness is not mystical. It is repetition of one move, noticing and returning, and it compounds like any training. Ten minutes a day is the smallest dose with evidence behind it.$v$, try_today = ARRAY[$v$Sit for ten minutes today. Phone in another room, timer set.$v$, $v$Breath as the anchor. When you notice you have wandered, come back; that is the rep.$v$, $v$Same time tomorrow. Never miss two days.$v$], key_takeaways = ARRAY[$v$Ten minutes a day for eight weeks; four weeks was not enough in the trial.$v$, $v$The rep is the return, not the focus.$v$, $v$Small to moderate effects, replicated; the full course matched an antidepressant in one trial.$v$], quiz = $v$[{"q": "What is the repetition you are training?", "choices": ["Staying perfectly focused", "Noticing the mind has wandered and coming back", "Sitting still"], "correct": 1, "explain": "Each return is one rep of attention control. Wandering is the set-up for the rep, not the failure."}, {"q": "What did Hoge's 2023 trial compare?", "choices": ["Meditation against exercise", "Ten minutes of a recording against nothing", "The full eight-week MBSR course against escitalopram, and found them equivalent"], "correct": 2, "explain": "276 adults with anxiety disorders; the full course, with classes and 45 minutes of daily practice."}, {"q": "How long did the brief-practice trial need for effects?", "choices": ["Eight weeks of about thirteen minutes a day", "One session", "Four weeks"], "correct": 0, "explain": "Basso 2019: eight weeks moved mood, attention and working memory in beginners; four weeks did not."}]$v$::jsonb, references_json = $v$[{"author": "Goyal, M. et al.", "title": "Meditation programs for psychological stress and well-being: a systematic review and meta-analysis (JAMA Intern. Med.)", "year": 2014}, {"author": "Hoge, E. A. et al.", "title": "Mindfulness-based stress reduction vs escitalopram for the treatment of adults with anxiety disorders: a randomized clinical trial (JAMA Psychiatry)", "year": 2023}, {"author": "Basso, J. C., McHale, A., Ende, V., Oberlin, D. J. & Suzuki, W. A.", "title": "Brief, daily meditation enhances attention, memory, mood, and emotional regulation in non-experienced meditators (Behav. Brain Res.)", "year": 2019}, {"author": "Hölzel, B. K. et al.", "title": "Mindfulness practice leads to increases in regional brain gray matter density (Psychiatry Res. Neuroimaging)", "year": 2011}, {"author": "Mrazek, M. D., Franklin, M. S., Phillips, D. T., Baird, B. & Schooler, J. W.", "title": "Mindfulness training improves working memory capacity and GRE performance while reducing mind wandering (Psychol. Sci.)", "year": 2013}, {"author": "Goldin, P. R. & Gross, J. J.", "title": "Effects of mindfulness-based stress reduction (MBSR) on emotion regulation in social anxiety disorder (Emotion)", "year": 2010}, {"author": "Pascoe, M. C., Thompson, D. R., Jenkins, Z. M. & Ski, C. F.", "title": "Mindfulness mediates the physiological markers of stress: systematic review and meta-analysis (J. Psychiatr. Res.)", "year": 2017}]$v$::jsonb, reflect_prompt = $v$When your attention leaves, where does it go first, and how long before you notice?$v$, integrate_prompt = $v$Two weeks in. Is the noticing arriving sooner, in the sit or outside it?$v$, practice_minutes = 10, lesson_number = 4, display_order = 4, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'mindfulness-mbsr';

UPDATE public.vault_articles SET title = $v$Cognitive Reframing$v$, subtitle = $v$Catch the thought, test the evidence, rewrite the line$v$, summary = $v$The core move of cognitive behavioural therapy: catch the thought, name the distortion, weigh the evidence, rewrite the line. It is the best-evidenced skill in psychology, and it takes five minutes when the feeling hits.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "5 to 10 min when triggered", "frequency": "On demand; daily in a hard period", "intensity": "Situation, automatic thought, distortion, evidence, reframe", "prerequisites": "None; severe depression or trauma goes with a therapist"}$v$::jsonb, benefits = ARRAY[$v$Fewer and shorter spirals$v$, $v$The skill of seeing a thought instead of being it$v$, $v$Effects equal to medication in trials, with lower relapse$v$, $v$Free, learnable from a book$v$], risks = ARRAY[$v$Severe depression or trauma: with a therapist, not alone$v$, $v$Not positive thinking; a reframe without evidence is a new distortion$v$, $v$When flooded, breathe first; the evidence is not available to you yet$v$], body_md = $v$**The premise**
Aaron Beck's observation in the 1960s was that events do not produce feelings directly; the interpretation in between does. Two people miss the same call and one reads rejection, the other a busy afternoon. The interpretation is fast, automatic and mostly invisible until you write it down, and it tends to follow a short list of distortions: catastrophising, all-or-nothing, mind-reading, personalising, the "should" that turns a preference into a law.

**The evidence**
Hofmann et al. (2012) identified 269 meta-analyses of cognitive behavioural therapy and reviewed 106 of them: large effects for anxiety disorders, and consistent effects for depression, insomnia, anger and chronic pain. DeRubeis et al. (2005) compared it head to head with an antidepressant in 240 people with moderate to severe depression: equal at sixteen weeks, with lower relapse a year after the treatment ended. Cuijpers et al. (2023) pooled 409 trials for depression and found the effect held across ages, cultures and severity. No other psychological skill has this much behind it.

**The five steps**
Catch the feeling first: the heat, the drop, the tightness. Write the situation in one line, facts only. Write the automatic thought word for word, even if it is ugly. Name the distortion. Then write the reframe: what you would tell a capable friend in the same spot, built from evidence, not from cheer. "She is angry with me" becomes "She has not replied in four hours; last time that happened she was in meetings and wrote in the evening; I will wait until tonight."

**How long it takes**
Five to ten minutes each time, when triggered, daily in a hard period. After about a month the catch happens in real time and the notebook is needed less. The Wisdom shelf's lesson on Epictetus is the same sort, done two thousand years earlier; this is the version with trials.

**When not to**
When you are flooded, the evidence is not available to you; breathe first, reframe later. Severe depression or trauma: do this with a therapist, who will pace it. And it is not positive thinking. A reframe that the evidence does not support is a new distortion.$v$, why_it_matters = $v$Events do not cause feelings; the sentence in between does. The same missed call can cost you a day or nothing, depending on the line you reach for, and the line is editable.$v$, try_today = ARRAY[$v$Catch one upsetting moment today and write the situation in one factual sentence.$v$, $v$Write the automatic thought word for word, then name its distortion.$v$, $v$List two pieces of evidence for it and two against, and write the balanced line.$v$], key_takeaways = ARRAY[$v$Trigger, thought, feeling: the thought is the lever.$v$, $v$Catch, write, name, weigh, rewrite; five minutes when the feeling hits.$v$, $v$The best-evidenced psychological skill there is; 106 meta-analyses reviewed.$v$], quiz = $v$[{"q": "In this model, what sits between an event and the feeling?", "choices": ["Nothing", "An automatic interpretation", "Hormones"], "correct": 1, "explain": "The event triggers a thought and the thought triggers the feeling. The thought is the one layer you can edit directly."}, {"q": "Which is a core reframing question?", "choices": ["Who is to blame?", "Why does this always happen to me?", "What is the evidence for and against this thought?"], "correct": 2, "explain": "Weighing evidence breaks the automatic loop and produces a more accurate line, which is the whole method."}, {"q": "DeRubeis 2005 found that against an antidepressant, this therapy was…", "choices": ["Equal at sixteen weeks, with lower relapse afterwards", "Untested", "Much weaker"], "correct": 0, "explain": "240 people with moderate to severe depression. The skill outlasted the pill once both stopped."}]$v$::jsonb, references_json = $v$[{"author": "Hofmann, S. G., Asnaani, A., Vonk, I. J. J., Sawyer, A. T. & Fang, A.", "title": "The efficacy of cognitive behavioral therapy: a review of meta-analyses (Cogn. Ther. Res.)", "year": 2012}, {"author": "DeRubeis, R. J. et al.", "title": "Cognitive therapy vs medications in the treatment of moderate to severe depression (Arch. Gen. Psychiatry)", "year": 2005}, {"author": "Cuijpers, P. et al.", "title": "Cognitive behavior therapy vs. control conditions, other psychotherapies, pharmacotherapies and combined treatment for depression: a comprehensive meta-analysis including 409 trials with 52,702 patients (World Psychiatry)", "year": 2023}, {"author": "Burns, D. D.", "title": "Feeling Good: The New Mood Therapy", "year": 1980}]$v$::jsonb, reflect_prompt = $v$What is the sentence you reach for first when something goes wrong, and whose voice is it in?$v$, integrate_prompt = $v$After a week of writing the thought down, did the catch start arriving before the feeling peaked?$v$, practice_minutes = 10, lesson_number = 5, display_order = 5, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'cognitive-reframing';

UPDATE public.vault_articles SET title = $v$Deep Work: Train Attention Like a Muscle$v$, subtitle = $v$Attention residue, the phone in the room, and one protected block a day$v$, summary = $v$Every switch leaves attention behind on the old task. One protected block a day, with the phone in another room, is how the capacity for sustained attention is rebuilt; it grows like a muscle and it starts at 25 minutes.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "25 to 90 min", "frequency": "One block a day, grown by five minutes a week", "intensity": "One task, phone in another room, notifications off", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$More finished work in fewer hours$v$, $v$Less of the frazzle that switching leaves$v$, $v$A capacity that grows with use$v$], risks = ARRAY[$v$Capacity builds gradually; a first 90-minute block usually fails, start at 25$v$, $v$Deep work is not for every task; the shallow work still needs its windows$v$], body_md = $v$**Attention residue**
Leroy (2009) gave people a task, interrupted it, and measured how well they did the next one. Part of their attention stayed on the unfinished task, and the next task suffered; she called it attention residue. Mark et al. (2005) shadowed knowledge workers through their days and found that once interrupted they took, on average, about 23 minutes to return to the original task. A day of switching feels busy and produces shallow work and a frazzled evening.

**The phone**
Ward et al. (2017) tested working memory with the phone on the desk, in a pocket or bag, or in another room. Face down and silent, it still cost capacity; in another room, the cost disappeared. The mere presence is the drain. Willpower against a visible phone is a losing bet; distance wins for free.

**Build the capacity**
One block a day for the most important task: 60 to 90 minutes if you can, 25 if you cannot, extended by five minutes a week. Phone in another room, notifications off, one browser tab. One task until the timer ends; when the urge to switch arrives, note it and return, which is the rep from lesson 4 applied to work. Batch the shallow work, email and messages, into two set windows. The aim is fewer, deeper hours, not more hours.

**What the evidence is and is not**
The residue and phone studies are real and replicated in the lab. The claim that protected blocks make you dramatically more productive over years is Newport's argument from cases, not a trial; it is plausible rather than proven, which is why the chip says promising. The habit is cheap to test on yourself in a week.

**Protect it**
Tell the people who would interrupt you. Put the block in the calendar as a meeting with yourself. The first week is uncomfortable; the discomfort is the residue clearing.$v$, why_it_matters = $v$Switching is the tax most working days pay without noticing. One protected block a day recovers the hours the tax was taking, and the capacity grows with use.$v$, try_today = ARRAY[$v$Block 60 minutes tomorrow for one important task, phone in another room.$v$, $v$Batch messages into two windows today and note how often you wanted to check.$v$, $v$If 60 minutes is impossible, start at 25 and add five a week.$v$], key_takeaways = ARRAY[$v$Every switch leaves residue; the next task runs slower.$v$, $v$The phone in another room beats the phone face down.$v$, $v$One protected block a day, grown by five minutes a week.$v$], quiz = $v$[{"q": "What did Ward's 2017 phone study find?", "choices": ["Face down is enough", "Even a silent phone on the desk cost working memory; another room removed the cost", "Phones improve focus"], "correct": 1, "explain": "The presence is the drain. Distance is free and it works without willpower."}, {"q": "What is attention residue?", "choices": ["A memory technique", "Tiredness", "Attention left on an interrupted task that slows the next one"], "correct": 2, "explain": "Leroy 2009. The unfinished task keeps a share of attention, and the next task pays for it."}]$v$::jsonb, references_json = $v$[{"author": "Leroy, S.", "title": "Why is it so hard to do my work? The challenge of attention residue when switching between work tasks (Organ. Behav. Hum. Decis. Process.)", "year": 2009}, {"author": "Mark, G., Gonzalez, V. M. & Harris, J.", "title": "No task left behind? Examining the nature of fragmented work (CHI)", "year": 2005}, {"author": "Ward, A. F., Duke, K., Gneezy, A. & Bos, M. W.", "title": "Brain drain: the mere presence of one's own smartphone reduces available cognitive capacity (J. Assoc. Consum. Res.)", "year": 2017}, {"author": "Newport, C.", "title": "Deep Work: Rules for Focused Success in a Distracted World", "year": 2016}]$v$::jsonb, reflect_prompt = $v$Where is your phone right now, and what would the next hour cost if it were in another room?$v$, integrate_prompt = $v$A week of one protected block. What got done that had been waiting?$v$, practice_minutes = 25, lesson_number = 6, display_order = 6, course_role = $v$protocol$v$, read_time_min = 2, updated_at = now() WHERE slug = 'deep-work-train-focus';

UPDATE public.vault_articles SET title = $v$The Five-Minute Journal$v$, subtitle = $v$Three lines in the morning, three at night$v$, summary = $v$Two minutes in the morning, three at night. Three things you are grateful for and one intention, then three things that went well and one lesson. The structure carries it, the gratitude has trials behind it, and it works because it is specific.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "2 min morning, 3 min evening", "frequency": "Daily", "intensity": "Three gratitudes, one when-then; three good things with the why, one lesson", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$A steadier baseline mood$v$, $v$A day that starts with a direction$v$, $v$A record of what worked, which is rarer than it sounds$v$], risks = ARRAY[$v$Toxic positivity is the trap; write real things, small ones on bad days$v$, $v$A journal does not treat depression; if the evening page is dark for weeks, talk to someone$v$], body_md = $v$**Why a structure**
A blank page at 07:00 gets nothing. A fixed shape, three lines and one line, gets filled in two minutes and survives a bad week. The morning half points the day; the evening half banks it.

**Morning, two minutes**
Three things you are grateful for, specific rather than grand: the coffee, the person who wrote back, the leg that is no longer sore. One line on what would make today good. One line on the first move of the day, written as a when-then: when I sit down at nine, I open the report before the inbox. Gollwitzer and Sheeran (2006) pooled 94 studies of that when-then form and found a medium to large effect on follow-through; it beats an affirmation because it hands the decision to the moment.

**Evening, three minutes**
Three things that went well, and why. One line on what could have gone better, as a lesson, not a verdict. Seligman et al. (2005) tested the three-good-things exercise against a placebo writing task: the group that wrote three good things and their causes for one week was happier and less depressed at six months. Emmons and McCullough (2003) found that weekly gratitude lists improved mood, sleep and even exercise compared with listing hassles. The effects are small and they replicate, which is what a five-minute habit should deliver.

**The rule that makes it work**
Specific and causal. "Training" is nothing; "I got the session in at 18:00 when the couch was the easier option, because I had written it in the calendar" re-scans the day for the win and its cause. That re-scan is the practice; the notebook is where it happens. Honest, not relentlessly upbeat: a bad day gets three small real things, not three invented ones.

**Where it fits**
The evening half pairs with the check-in in the app, which already asks for the day. The Inner Work shelf's lesson on gratitude has the wider evidence; this is the five-minute version.$v$, why_it_matters = $v$Attention flags problems first and filters wins out; that is useful for survival and bad for baseline mood. Five minutes a day corrects the filter by hand, and the correction compounds.$v$, try_today = ARRAY[$v$Tomorrow morning: three gratitudes, one line on a good day, one when-then for the first move.$v$, $v$Tonight: three things that went well and why, and one lesson.$v$, $v$Keep it to five minutes; the length is the point.$v$], key_takeaways = ARRAY[$v$Morning points the day, evening banks it; five minutes in total.$v$, $v$Specific and causal, or it does nothing.$v$, $v$Three good things for one week was still measurable at six months.$v$], quiz = $v$[{"q": "What makes an entry work?", "choices": ["Specific detail and the reason why", "A nice notebook", "Length"], "correct": 0, "explain": "The re-scan for the win and its cause is the practice. Generic lists skip it."}, {"q": "What did Seligman's 2005 trial find for three good things?", "choices": ["No effect", "Happier and less depressed at six months after one week of practice", "It worked only in the first week"], "correct": 1, "explain": "Against a placebo writing task. Small effects, and they lasted."}]$v$::jsonb, references_json = $v$[{"author": "Seligman, M. E. P., Steen, T. A., Park, N. & Peterson, C.", "title": "Positive psychology progress: empirical validation of interventions (Am. Psychol.)", "year": 2005}, {"author": "Emmons, R. A. & McCullough, M. E.", "title": "Counting blessings versus burdens: an experimental investigation of gratitude and subjective well-being in daily life (J. Pers. Soc. Psychol.)", "year": 2003}, {"author": "Gollwitzer, P. M. & Sheeran, P.", "title": "Implementation intentions and goal achievement: a meta-analysis of effects and processes (Adv. Exp. Soc. Psychol.)", "year": 2006}]$v$::jsonb, reflect_prompt = $v$What does your mind replay at night, and how much of it went well?$v$, integrate_prompt = $v$A week of the journal. Did the day's wins start showing up before you sat down to write them?$v$, practice_minutes = 5, lesson_number = 7, display_order = 7, course_role = $v$protocol$v$, read_time_min = 2, updated_at = now() WHERE slug = 'five-minute-journal';
